type Profile={schemaVersion:string;profileId:string;profileVersion:string;targetPlanet:string;dimensions:{id:string;name:string;factors:{id:string;name:string;definition?:string;unit:string;requirementStatus:string;evidenceAvailability:{status:string;provider:string|null;dataset?:string|null;observationPeriod?:string|null;spatialResolution?:string|null;temporalResolution?:string|null;availableSiteIds:string[]};limitations:string[]}[]}[];missions:{id:string;name:string;objective:string;requiredFactorIds:string[];optionalFactorIds:string[];currentEvidenceState:string;limitations:string[]}[]};
